package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.content.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.articles.*;
import com.lianxibu.site.service.content.*;
import com.lianxibu.site.service.jobs.GenerationFlowService.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.support.TransactionSynchronizationManager;
/** Formal preparation uses actual whole native source/admission, metadata, request builder and native storage. Genesis source/model/settings are fictional. */
class ReportPreparationServiceTest {
 boolean mysql(){return false;}
 ReportInputWriterAdmissionTest.Period x;ReportPreparationService service;ReportPreparedInputService originals;
 GenerationRequestBuilder requests;ReportInputWriterAdmissionService admission;FrozenGenerationSettings preferences=new FrozenGenerationSettings(1,List.of(),List.of());
 boolean allowed=true;int settingsReads,requestBuilds;Runnable afterRequest=()->{};Clock clock;
 void setup(){x=new ReportInputWriterAdmissionTest(){@Override boolean mysql(){return ReportPreparationServiceTest.this.mysql();}}.admitted();var base=x.nativeData().f.h.h.f;originals=new ReportPreparedInputService(base.source,base.tx);admission=spy(x.admission());requests=spy(new GenerationRequestBuilder());doAnswer(call->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());requestBuilds++;var result=call.callRealMethod();afterRequest.run();return result;}).when(requests).build(any(),anyString(),anyString());clock=Clock.fixed(x.captured().cutoff().plusNanos(123456000),ZoneOffset.UTC);compose();}
 void compose(){var base=x.nativeData().f.h.h.f;var versions=new FrozenContentVersionService(new JdbcFrozenContentVersions(base.source));var metadata=new ReportPublicMetadataEnricher(mock(ArticlePublicEvidenceService.class),mock(SourceMemberEvidenceService.class),versions);service=new ReportPreparationService(base.source,originals,admission,base.writes,()->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertFalse(TransactionSynchronizationManager.isCurrentTransactionReadOnly());settingsReads++;return preferences;},metadata,requests,clock,()->allowed);}
 ReportPreparedInputService.Prepared prepare(){return ReportOriginalCompletionTest.utc(()->service.prepare(x.captured().scope()));}
 @Test void ActualFullInitialPeriodPreparesOneOriginalNativeRequestAndReplaysBeforeAllMutableProviders(){setup();var first=prepare();assertEquals("queued",first.input().state());assertEquals(1,requestBuilds);assertEquals(1,x.nativeData().f.h.h.f.sends);assertEquals("deepseek-flash",CanonicalJson.parse(first.input().requestJson()).get("model").asText());assertEquals(ReportPreparationService.contentId(x.captured().scope()),ReportPreparationInputProfile.complete(CanonicalJson.parse(first.input().snapshotJson())).command().applicationContext().contentId());int reads=settingsReads;clearInvocations(admission,requests);allowed=false;preferences=new FrozenGenerationSettings(2,List.of("Fictional later topic"),List.of());clock=mock(Clock.class);compose();var second=service.prepare(x.captured().scope());assertEquals(first,second);assertEquals(reads,settingsReads);verifyNoInteractions(admission,requests,clock);assertEquals(1,requestBuilds);}
 @Test void ActualNaturalMonthUsesOriginalDailyBodyAndEveryUnknownDateWithoutNoUpdateFallback(){setup();var last=LocalDate.parse("2026-01-31");clock=Clock.fixed(last.plusDays(1).atTime(5,0).atZone(ZoneId.of("Asia/Shanghai")).toInstant().plusNanos(123456000),ZoneOffset.UTC);compose();var scope=new ReportInputCaptureService.Scope("report:monthly:"+last,1,Stage.MONTHLY_REPORT,last);var prepared=ReportOriginalCompletionTest.utc(()->service.prepare(scope));var full=CanonicalJson.parse(prepared.input().snapshotJson());assertEquals(30,full.get(ReportInputProfile.FIELD).get("coverage").get("missing_dates").size());assertTrue(full.get(ReportInputProfile.FIELD).get("coverage").get("no_update_dates").isEmpty());assertEquals("partial",prepared.input().coverageState());assertEquals(1,requestBuilds);}
 @Test void SourceOrSettingsChangesAfterPureRequestBuildRejectFinalNativeWriteWithoutPartialRoot(){setup();afterRequest=()->x.nativeData().f.h.h.f.jdbc.update("UPDATE contents SET state='blocked'");assertThrows(RuntimeException.class,this::prepare);String root=JdbcReportPreparedInputs.root(x.captured().scope().logicalKey(),1);assertNull(new JdbcJobRecords(x.nativeData().f.h.h.f.source).byId(root));assertNull(originals.find(x.captured().scope()));setup();afterRequest=()->preferences=new FrozenGenerationSettings(2,List.of("Fictional changed"),List.of());assertThrows(RuntimeException.class,this::prepare);assertNull(originals.find(x.captured().scope()));}
 @Test void NativeReceiptFailureRollsBackAllNewInputsAndAttemptsWhileOriginalSourceRemains(){setup();var base=x.nativeData().f.h.h.f;base.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_new_report_prepare_failure CHECK(target_type IS NULL OR operator_id<>'report-coordinator' OR target_type<>'generation_prepare')");assertThrows(RuntimeException.class,this::prepare);assertNull(originals.find(x.captured().scope()));assertEquals(1,base.sends);assertEquals(1,requestBuilds);}
 @Test void ColdMandatoryProvidersUtcRuntimeEarlyCutoffAndPreparationSwitchAreExplicit(){setup();var base=x.nativeData().f.h.h.f;var clock=mock(Clock.class);var nativeReader=mock(ReportPreparedInputService.class);var source=mock(javax.sql.DataSource.class);var inputs=mock(ReportInputWriterAdmissionService.class);var writer=mock(SharedWriteExecutor.class);var setting=mock(SettingsSnapshotSource.class);var meta=mock(ReportPublicMetadataEnricher.class);var req=mock(GenerationRequestBuilder.class);new ReportPreparationService(source,nativeReader,inputs,writer,setting,meta,req,clock,()->true);verifyNoInteractions(source,nativeReader,inputs,writer,setting,meta,req,clock);allowed=false;assertThrows(RuntimeException.class,this::prepare);assertNull(originals.find(x.captured().scope()));allowed=true;this.clock=Clock.fixed(x.captured().cutoff().minusSeconds(1),ZoneOffset.UTC);compose();assertThrows(RuntimeException.class,this::prepare);assertEquals(0,requestBuilds);var old=TimeZone.getDefault();try{TimeZone.setDefault(TimeZone.getTimeZone("Asia/Shanghai"));assertThrows(RuntimeException.class,()->service.prepare(x.captured().scope()));}finally{TimeZone.setDefault(old);}assertNull(originals.find(x.captured().scope()));}
}
